            if (step == 0) throw new ArgumentException("slice step cannot be zero");
            long len = r.Count;
            long Norm(long? v, long dflt, long lo, long hi)
            {
                if (v == null) return dflt;
                long x = v.Value < 0 ? v.Value + len : v.Value;
                return Math.Clamp(x, lo, hi);
            }
            long a = step > 0 ? Norm(start, 0, 0, len) : Norm(start, len - 1, -1, len - 1);
            long b = step > 0 ? Norm(stop, len, 0, len) : Norm(stop, -1, -1, len - 1);
            return new PyRange(r.Start + a * r.Step, r.Start + b * r.Step, r.Step * step);
        }
        public static dynamic slice(object o, long? start, long? stop, long step = 1)
        {
            // a late-bound str, list or array: the slice of its run-time type (steps included)
            if (o is PyRange pr) return slice(pr, start, stop, step);
            if (o is string str0) return slice(str0, start, stop, step);
            if (o is System.Collections.IList && (o.GetType().IsArray || o.GetType().IsGenericType)) return slice((dynamic)o, start, stop, step);
            // a tuple of fixed shape (a ValueTuple): its slice is a tuple of the selected items
            if (o is ITuple tuple)
            {
                var items = new object?[tuple.Length];
                for (int i = 0; i < items.Length; i++) items[i] = tuple[i];
                return new PyTuple<object?>(slice((IList<object?>)items, start, stop, step));
            }
            if (TryGetAttr(o, "__getitem__", out var index, allowFallback: false))
                return __invoke(index, [new PySlice(start, stop, step)]);
            if (step != 1) throw new NotSupportedException("stepped slices are only supported on str, list and arrays");
            Index s = start == null ? Index.Start : start.Value < 0 ? Index.FromEnd(checked((int)-start.Value)) : Index.FromStart(checked((int)start.Value));
            Index e = stop == null ? Index.End : stop.Value < 0 ? Index.FromEnd(checked((int)-stop.Value)) : Index.FromStart(checked((int)stop.Value));
            return ((dynamic)o)[new Range(s, e)];
        }


        public static void setslice<T>(List<T> l, long? start, long? stop, long step, IEnumerable<T> values)
        {
            var vals = ReferenceEquals(values, l) ? new List<T>(l) : values as IList<T> ?? values.ToList();
            if (step == 1)
            {
                var (a, b) = SliceBounds(l.Count, start, stop);
                l.RemoveRange(a, b - a);
                l.InsertRange(a, vals);
                return;
            }
            var idx = SliceIndices(l.Count, start, stop, step);
            if (idx.Count != vals.Count) throw new ArgumentException($"attempt to assign sequence of size {vals.Count} to extended slice of size {idx.Count}");
            for (int i = 0; i < idx.Count; i++) l[idx[i]] = vals[i];
        }
        /// <summary>
        /// xs[a:b] = ys on late-bound values: the items are converted to the list's item type and assigned by the typed
        /// version (dispatching dynamically would come back here when the item types differ).
        /// </summary>
        public static void setslice(object l, long? start, long? stop, long step, object values)
        {
            // ba[a:b] = data: any bytes-like value (bytes, bytearray, memoryview, a list of ints)
            if (l is PyByteArray ba) { setslice(ba.Buffer, start, stop, step, ByteOps.From(values)); return; }
            if (l is global::memoryview view) { view.SetSlice(start, stop, step, values); return; }
            var itemType = EnumerableItemType(l.GetType());
            if (itemType == null || l is not IList) throw new InvalidCastException($"'{l.GetType().Name}' object does not support slice assignment");
            var typed = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(itemType))!;
            foreach (object? v in __iter_dyn(values))
                typed.Add(v == null || itemType.IsInstanceOfType(v) || itemType == typeof(object) ? v : Convert.ChangeType(v, Nullable.GetUnderlyingType(itemType) ?? itemType, CultureInfo.InvariantCulture));
            var generic = typeof(Builtins).GetMethods().First(m => m.Name == nameof(setslice) && m.IsGenericMethodDefinition);
            generic.MakeGenericMethod(itemType).Invoke(null, new object?[] { l, start, stop, step, typed });
        }

        public static void delslice<T>(List<T> l, long? start, long? stop, long step = 1)
        {
            if (step == 1) { var (a, b) = SliceBounds(l.Count, start, stop); l.RemoveRange(a, b - a); return; }
            var idx = SliceIndices(l.Count, start, stop, step);
            idx.Sort();
            for (int i = idx.Count - 1; i >= 0; i--) l.RemoveAt(idx[i]);
        }


        /// <summary>Element i of a sequence passed as f(*xs) to n fixed parameters (Python checks the count).</summary>
        public static T __unpack<T>(IList<T> xs, int i, int n) =>
            xs.Count == n ? xs[i] : throw new InvalidCastException($"expected {n} positional arguments from *args, got {xs.Count}");
        public static dynamic __unpack(object xs, int i, int n) => xs is ITuple t && !(xs is IEnumerable)
            ? (t.Length == n ? t[i]! : throw new InvalidCastException($"expected {n} positional arguments from *args, got {t.Length}")) // a tuple of fixed shape
            : __unpack(((IEnumerable)xs).Cast<object?>().ToList(), i, n)!;

        /// <summary>Fixed-arity unpacking reads up to one extra item to check for surplus values.</summary>
        public static T[] __unpack_items<T>(IEnumerable<T> source, int count)
        {
            var items = new T[count];
            using var iterator = source.GetEnumerator();
            for (int i = 0; i < count; i++)
            {
                if (!iterator.MoveNext())
                    throw new ArgumentException($"not enough values to unpack (expected {count}, got {i})");
                items[i] = iterator.Current;
            }
            if (iterator.MoveNext())
                throw new ArgumentException($"too many values to unpack (expected {count})");
            return items;
        }

        public static OrderedDictionary<K, V> __dict_merge<K, V>(params IEnumerable<KeyValuePair<K, V>>[] parts) where K : notnull
        {
            var d = new OrderedDictionary<K, V>();
            foreach (var part in parts) foreach (var kv in part) d[kv.Key] = kv.Value;
            return d;
        }
        /// <summary>{**a, **b} of dicts with different key/value types: the result has the unified types.</summary>
        public static OrderedDictionary<K, V> __dict_merge_as<K, V>(params IDictionary[] parts) where K : notnull
        {
            var d = new OrderedDictionary<K, V>();
            foreach (var part in parts) foreach (DictionaryEntry e in part) d[(K)e.Key] = (V)e.Value!;
            return d;
        }


        static void CheckUnpack(int count, int expected)
        {
            if (count != expected) throw new ArgumentException(count > expected ? $"too many values to unpack (expected {expected})" : $"not enough values to unpack (expected {expected}, got {count})");
        }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b) { CheckUnpack(l.Count, 2); a = l[0]; b = l[1]; }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b, out T c) { CheckUnpack(l.Count, 3); a = l[0]; b = l[1]; c = l[2]; }
        public static void Deconstruct<T>(this IList<T> l, out T a, out T b, out T c, out T d) { CheckUnpack(l.Count, 4); a = l[0]; b = l[1]; c = l[2]; d = l[3]; }


        public static void append<T>(this List<T> l, T x) => l.Add(x);
        public static void extend<T>(this List<T> l, IEnumerable<T> xs) => l.AddRange(xs);
        /// <summary>A list of late-bound (or wider) items extended with typed ones: List&lt;dynamic&gt; += List&lt;long&gt;.</summary>
        public static void __extend_cast<T, U>(List<T> l, IEnumerable<U> xs) { foreach (var x in xs) l.Add((T)(dynamic)x!); }
        /// <summary>Does a late-bound method use the runtime implementation for its builtin receiver?</summary>
        public static bool __uses_builtin_method(object? o, string name)
        {
            if (o is string or IConvertible or BigInteger) return true;
            if (o is Task && name is ("send" or "close")) return true;
            if (o is Exception && name == "add_note") return !HasSourceMember(o.GetType(), name);
            if (o == null) return false;
            Type type = o.GetType();
            if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(frozendict<,>)) return false;
            bool builtinShape = o is ITuple or IList || o is IDictionary and not (Typhon.Stdlib.types.MappingProxyType or PyAttrDict) ||
                type.IsGenericType && type.GetGenericTypeDefinition() == typeof(HashSet<>);
            return builtinShape && !HasSourceMember(type, name);
        }

        /// <summary>a += b on late-bound values: a list extends in place (Python's list.__iadd__), anything else adds.</summary>
        public static dynamic __iadd(dynamic a, dynamic b)
        {
            if (a is System.Collections.IList list && !(b is string)) { foreach (var x in (IEnumerable)b) list.Add(x); return a; }
            return add((object?)a, (object?)b);
        }
        public static void insert<T>(this List<T> l, long i, T x) => l.Insert((int)(i < 0 ? Math.Max(0, l.Count + i) : Math.Min(i, l.Count)), x);
        public static void insert<T>(this List<T> l, BigInteger i, T x) => insert(l, checked((long)i), x);
        public static T pop<T>(this List<T> l, long i = -1)
        {
            if (i < 0) i += l.Count;
            if ((ulong)i >= (ulong)l.Count) throw new ArgumentOutOfRangeException(nameof(i), l.Count == 0 ? "pop from empty list" : "pop index out of range");
            var x = l[(int)i]; l.RemoveAt((int)i); return x;
        }
        public static void remove<T>(this List<T> l, T x) { if (!l.Remove(x)) throw new ArgumentException("list.remove(x): x not in list"); }
        public static long index<T>(this IList<T> l, T x) { int i = l.IndexOf(x); return i >= 0 ? i : throw new ArgumentException("value is not in list"); }
        public static long index<T>(this IList<T> l, T x, long start, long? stop = null)
        {
            var (a, b) = SliceBounds(l.Count, start, stop);
            for (int i = a; i < b; i++) if (EqualityComparer<T>.Default.Equals(l[i], x)) return i;
            throw new ArgumentException("value is not in list");
        }
        public static long count<T>(this IEnumerable<T> l, T x) => l.LongCount(y => Equals(y, x));
        public static void sort<T>(this List<T> l, bool reverse = false)
        {
            if (StabilityIrrelevant<T>()) { l.Sort(PyComparer<T>()); if (reverse) l.Reverse(); return; }
            var s = sorted(l, reverse);
            l.Clear(); l.AddRange(s);
        }
        public static void sort<T, K>(this List<T> l, Func<T, K> key, bool reverse = false) { var s = sorted(l, key, reverse); l.Clear(); l.AddRange(s); }
        public static void sort<T>(this List<T> items, PyClosure? key, bool reverse = false)
        {
            var sortedItems = sorted(items, key, reverse);
            items.Clear();
            items.AddRange(sortedItems);
        }

        public static void reverse<T>(this List<T> l) => l.Reverse();
        public static List<T> copy<T>(this List<T> l) => new List<T>(l);
        public static void clear<T>(this ICollection<T> c) => c.Clear();
    }
